"python -c "import csv, hashlib, sys
sys.stdout.reconfigure(encoding='utf-8')
with open('dataset/user_identities.csv', encoding='utf-8') as f:
    users = {u['user_id']: u for u in csv.DictReader(f)}
with open('dataset/user_audit_log.csv', encoding='utf-8') as f:
    audits = list(csv.DictReader(f))

def get_profile(uid, audit_at):
    u = users[uid]
    emails = {u['email'].lower()}
    phones = {u['phone']}
    names = {u['name']}
    hashes = {u['email_hash'].lower()}
    user_audits = [a for a in audits if a['user_id'] == uid and a['event_time'] <= audit_at]
    for a in user_audits:
        fn = a['field_name']
        if fn == 'email':
            emails.add(a['old_value'].lower())
            emails.add(a['new_value'].lower())
        elif fn == 'phone':
            phones.add(a['old_value'])
            phones.add(a['new_value'])
        elif fn == 'email_hash':
            hashes.add(a['old_value'].lower())
            hashes.add(a['new_value'].lower())
        elif fn == 'name':
            names.add(a['old_value'])
            names.add(a['new_value'])
    for e in list(emails):
        hashes.add(hashlib.sha256(e.encode()).hexdigest())
    return {
        'user_id': uid,
        'emails': emails,
        'phones': phones,
        'names': names,
        'email_hashes': hashes,
        'audits_count': len(user_audits)
    }

for uid, audit_at in [('user_10', '2026-09-18T12:25:00Z'), ('user_29', '2026-09-15T12:00:00Z'), ('user_01', '2026-09-03T11:30:00Z')]:
    prof = get_profile(uid, audit_at)
    print(f'=== Profile {uid} ===')
    print('Emails:', prof['emails'])
    print('Phones:', prof['phones'])
    print('Names:', prof['names'])
    print('Hashes count:', len(prof['email_hashes']))
    print('Audits:', prof['audits_count'])
