"import glob
import os
import sqlite3

sql_files = glob.glob('dataset/evidence/databases/*.sql')
print(f"Total SQL files: {len(sql_files)}")

target_accounts = ['account_5482', 'account_3866', 'account_3136', 'account_5334', 'account_5684', 'account_6440', 'account_7566', 'account_3960', 'account_4857', 'account_8858']

for p in sorted(sql_files):
    fname = os.path.basename(p)
    try:
        con = sqlite3.connect(':memory:')
        with open(p, 'r', encoding='utf-8') as f:
            con.executescript(f.read())
        cur = con.cursor()
        tables = [t[0] for t in cur.execute("SELECT name FROM sqlite_master WHERE type='table'")]
        for t in tables:
            for acc in target_accounts:
                try:
                    rows = cur.execute(f"SELECT * FROM {t} WHERE resource_id='{acc}'").fetchall()
                    if rows:
                        print(f"[{fname}] {t} found {acc}: {rows}")
                except:
                    # Maybe resource_id is in record_json
                    try:
                        rows = cur.execute(f"SELECT * FROM {t} WHERE record_json LIKE '%{acc}%'").fetchall()
                        if rows:
                            print(f"[{fname}] {t} (json) found {acc}: {rows[0]}")
                    except:
                        pass
        con.close()
    except Exception as e:
        pass
"

