cases_to_inspect = ['case_05', 'case_07', 'case_10', 'case_12', 'case_14', 'case_28']

for cid in cases_to_inspect:
    status, steps = sample_out[cid]
    print(f"\n=== {cid} ({status}) ===")
    for s in steps:
        print(f"  step {s['step_no']}: {s['phase']} | {s['system_id']} | {s['resource_id']} | {s['operation']} | {s['state']} | ev={s['evidence_id']}")
"

